func (m OntologyMorphism) Validate() error {
	if err := validateTypedID(m.id, "morphism"); err != nil {
		return err
	}
	if m.safety == "" || m.safety != safetyForMorphism(m.kind) {
		return invalid("morphism safety does not match its kind")
	}
	if err := m.source.Validate(); err != nil {
		return err
	}
	if err := m.target.Validate(); err != nil {
		return err
	}
	if err := m.sourceVersion.Validate(); err != nil {
		return err
	}
	if err := m.targetVersion.Validate(); err != nil {
		return err
	}
	source, _ := NewOntologyIdentity(m.sourceVersion)
	target, _ := NewOntologyIdentity(m.targetVersion)
	if source != m.source || target != m.target {
		return invalid("morphism version material does not match its identities")
	}
	if m.source.SchemaID() != m.target.SchemaID() ||
		m.source.VersionID() == m.target.VersionID() {
		return invalid("morphism must connect distinct versions of one schema")
	}
	if !requiredWire(m.rationale) || len(m.evidence) == 0 {
		return invalid("morphism rationale and evidence are required")
	}
	if len(m.evidence) > MaxMorphismEvidence {
		return invalid("morphism evidence exceeds the public bound")
	}
	for i, evidence := range m.evidence {
		if err := evidence.Validate(); err != nil {
			return err
		}
		if _, derived := evidence.Derivation(); derived {
			return invalid("morphism evidence must cite an immutable source observation")
		}
		if i > 0 && m.evidence[i-1].ID() >= evidence.ID() {
			return invalid("morphism evidence must be unique and ordered")
		}
	}
	if err := validateMorphismIDs(m.sources, "morphism sources"); err != nil {
		return err
	}
	if err := validateMorphismIDs(m.targets, "morphism targets"); err != nil {
		return err
	}
	if m.kind != MorphismSplit && m.discriminator.Known() {
		return invalid("only split morphisms may carry a discriminator")
	}

	switch m.kind {
	case MorphismWiden, MorphismNarrow:
		if len(m.sources) != 1 || len(m.targets) != 1 || m.sources[0] != m.targets[0] ||
			IDNamespace(m.sources[0]) != "relationship" {
			return invalid("domain/range morphism requires one unchanged relationship identity")
		}
	case MorphismRename:
		if len(m.sources) != 1 || len(m.targets) != 1 ||
			m.sources[0] == m.targets[0] ||
			IDNamespace(m.sources[0]) != IDNamespace(m.targets[0]) {
			return invalid("rename requires one source and one distinct same-kind target")
		}
	case MorphismSplit:
		if len(m.sources) != 1 || len(m.targets) < 2 {
			return invalid("split requires one source and multiple targets")
		}
		if !sameDefinitionNamespace(m.sources, m.targets) {
			return invalid("split source and targets must have the same definition kind")
		}
		if err := m.discriminator.Validate(); err != nil {
			return err
		}
		covered := map[shoal.ID]bool{}
		for _, choice := range m.discriminator.choices {
			if !containsID(m.targets, choice.target) {
				return invalid("split discriminator points outside targets")
			}
			covered[choice.target] = true
		}
		if len(covered) != len(m.targets) {
			return invalid("split discriminator must cover every target")
		}
	case MorphismMerge:
		if len(m.sources) < 2 || len(m.targets) != 1 {
			return invalid("merge requires multiple sources and one target")
		}
		if !sameDefinitionNamespace(m.targets, m.sources) {
			return invalid("merge sources and target must have the same definition kind")
		}
	default:
		return invalid("unknown morphism kind")
	}

	for _, id := range append(append([]shoal.ID(nil), m.sources...), m.targets...) {
		if ValidateID(id) != nil {
			return invalid("morphism definition identity is invalid")
		}
	}
	if err := validateMetadata(m.metadata); err != nil {
		return err
	}
	expected, err := morphismID(m)
	if err != nil || expected != m.id {
		return invalid("morphism ID is not canonical")
	}
	return nil
}

func ontologyConceptBoundProposal(
	t *testing.T, count uint32,
) (ontology.GovernedProposal, ontology.OntologyVersion) {
	t.Helper()
	base := ontologyBoundVersion(t, 0)
	concepts := make([]ontology.ConceptDefinition, 0, count)
	for index := uint32(0); index < count; index++ {
		concept, err := ontology.NewConceptDefinition(
			fmt.Sprintf("concept-%03d", index), "Concept", "", nil, nil)
		if err != nil {
			t.Fatal(err)
		}
		concepts = append(concepts, concept)
	}
	target, err := ontology.NewOntologyVersion(
		base.Schema(), "next", base.CreatedAt().Add(time.Second), concepts, nil, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	return ontologyBoundProposal(t, base, target), base
}

// NewDecision validates, canonicalizes, and defensively owns a trusted
// decision. Authentication expiry is checked when the decision is bound,
// resolved, or authorized.
func NewDecision(config DecisionConfig) (Decision, error) {
	if err := shoal.ValidateRequiredID("subject", config.Subject); err != nil {
		return Decision{}, err
	}
	if err := shoal.ValidateRequiredID("actor", config.Actor); err != nil {
		return Decision{}, err
	}
	if err := shoal.ValidateRequiredID("request ID", config.RequestID); err != nil {
		return Decision{}, err
	}
	if err := shoal.ValidateOptionalID("client ID", config.ClientID); err != nil {
		return Decision{}, err
	}
	if err := shoal.ValidateOptionalID("correlation ID", config.CorrelationID); err != nil {
		return Decision{}, err
	}
	if err := shoal.ValidateOptionalID(
		"service ceiling", config.ServiceCeilingIdentity,
	); err != nil {
		return Decision{}, err
	}
	if len(config.OnBehalfOf) > MaxOnBehalfOfEntries {
		return Decision{}, shoal.NewError(
			shoal.ErrorInvalidArgument, "on-behalf-of chain exceeds the public bound")
	}
	onBehalfOf := append([]shoal.ID(nil), config.OnBehalfOf...)
	for _, identity := range onBehalfOf {
		if err := shoal.ValidateRequiredID("on-behalf-of identity", identity); err != nil {
			return Decision{}, err
		}
	}
	if err := validatePolicyComponent(
		"authorization domain", config.AuthorizationDomain, true,
	); err != nil {
		return Decision{}, err
	}
	if len(config.PermittedSourceIDs) > MaxDecisionGrantIDs ||
		len(config.PermittedPolicyIDs) > MaxDecisionGrantIDs {
		return Decision{}, shoal.NewError(
			shoal.ErrorInvalidArgument, "decision grants exceed the public ID bound")
	}
	operations, err := normalizeOperations(config.AllowedOperations)
	if err != nil {
		return Decision{}, err
	}
	sources, err := sortedUniqueBytes(
		"permitted source identity", config.PermittedSourceIDs, true)
	if err != nil {
		return Decision{}, err
	}
	policies, err := sortedUniqueBytes(
		"permitted policy identity", config.PermittedPolicyIDs, true)
	if err != nil {
		return Decision{}, err
	}
	if config.PolicyGeneration <= 0 {
		return Decision{}, shoal.NewError(
			shoal.ErrorInvalidArgument, "policy generation must be positive")
	}
	if config.AuthenticationExpires.IsZero() {
		return Decision{}, shoal.NewError(
			shoal.ErrorInvalidArgument, "authentication expiry is required")
	}
	expiresAt := config.AuthenticationExpires.UTC()
	if year := expiresAt.Year(); year < 1 || year > 9999 {
		return Decision{}, shoal.NewError(
			shoal.ErrorInvalidArgument, "authentication expiry is outside the supported range")
	}
	if err := validateOptionalSemantic("audit purpose", config.AuditPurpose); err != nil {
		return Decision{}, err
	}
	if config.SelectedOntology.Known() {
		if err := config.SelectedOntology.Validate(); err != nil {
			return Decision{}, err
		}
	}
	if config.ServiceRole == "" {
		if config.ServiceCeilingIdentity != "" {
			return Decision{}, shoal.NewError(
				shoal.ErrorInvalidArgument,
				"service ceiling identity requires a service role",
			)
		}
	} else {
		if err := config.ServiceRole.Validate(); err != nil {
			return Decision{}, err
		}
		if err := shoal.ValidateRequiredID(
			"service ceiling identity", config.ServiceCeilingIdentity,
		); err != nil {
			return Decision{}, err
		}
		for _, operation := range operations {
			if !config.ServiceRole.Allows(operation) {
				return Decision{}, shoal.NewError(
					shoal.ErrorInvalidArgument,
					"allowed operation exceeds the service role ceiling",
				)
			}
		}
	}

	return Decision{
		subject:                config.Subject,
		actor:                  config.Actor,
		clientID:               config.ClientID,
		onBehalfOf:             onBehalfOf,
		domain:                 cloneBytes(config.AuthorizationDomain),
		operations:             operations,
		sources:                sources,
		policies:               policies,
		policyGeneration:       config.PolicyGeneration,
		expiresAt:              expiresAt,
		requestID:              config.RequestID,
		correlationID:          config.CorrelationID,
		auditPurpose:           config.AuditPurpose,
		serviceRole:            config.ServiceRole,
		serviceCeilingIdentity: config.ServiceCeilingIdentity,
		selectedOntology:       config.SelectedOntology,
	}, nil
}

