func TestRecoveryRestoresAmbiguousRecordAttemptBinding(t *testing.T) {
	for _, applied := range []bool{false, true} {
		t.Run(map[bool]string{false: "not applied", true: "applied"}[applied], func(t *testing.T) {
			config := testRuntimeConfig(t, testDirectory(t))
			runtime, err := Open(config)
			if err != nil {
				t.Fatal(err)
			}
			defer runtime.Close()
			faults := &ambiguousAttemptStore{
				EngineStore: runtime.store,
				apply:       applied,
			}
			runtime.intents.store = faults
			request := testRecordPublication(
				"document",
				"revision",
				"value",
				nil,
			)
			if _, err := runtime.PublishRecord(
				context.Background(),
				request,
			); !errors.Is(err, ErrIndeterminatePublication) ||
				!errors.Is(err, allocator.ErrConditionalUnknown) {
				t.Fatalf("ambiguous record binding = %v", err)
			}

			runtime.intents.store = runtime.store
			if err := runtime.Recover(context.Background()); err != nil {
				t.Fatalf("recover ambiguous record binding = %v", err)
			}
			attempt, err := runtime.RecordAttempt(context.Background(), request)
			if err != nil || attempt == nil ||
				!bytes.Equal(attempt.Value, request.Value) ||
				attempt.ExpectedEpoch != request.ExpectedEpoch ||
				attempt.ExpectedDigest != request.ExpectedDigest {
				t.Fatalf("recovered record attempt = %#v, %v", attempt, err)
			}
			head, err := runtime.RecordHead(
				context.Background(),
				request.EntityKind,
				request.EntityID,
			)
			if err != nil || head == nil {
				t.Fatalf("recovered record head = %#v, %v", head, err)
			}
			retry, err := runtime.PublishRecord(context.Background(), request)
			if err != nil || !retry.Unchanged || retry.Epoch != head.Epoch {
				t.Fatalf("exact retry after binding recovery = %#v, %v", retry, err)
			}
			after, err := runtime.CurrentHead(context.Background())
			if err != nil || after.Frontier != head.Epoch {
				t.Fatalf("retry duplicated recovered publication = %#v, %v", after, err)
			}
		})
	}
}

func (e *Explorer) documentRecordAttempt(
	ctx context.Context,
	row []byte,
) (*persistedDocument, *RecordPublicationHead, []byte, bool, error) {
	if e.publication == nil {
		return nil, nil, nil, false, nil
	}
	attempt, err := e.publication.RecordAttempt(
		ctx, documentRecordAttemptProbe(row),
	)
	if err != nil {
		return nil, nil, nil, false, shoal.WrapError(
			shoal.ErrorUnavailable, "read transactional document attempt", err,
		)
	}
	if attempt == nil {
		return nil, nil, nil, false, nil
	}
	var record persistedDocument
	if err := decodeEmbeddedRecord(
		attempt.Value, embeddedRecordDocument, &record,
	); err != nil {
		return nil, nil, nil, false, shoal.WrapError(
			shoal.ErrorInternal, "decode transactional document attempt", err,
		)
	}
	if err := validatePersistedDocument(record); err != nil ||
		!bytes.Equal(row, documentRecordRow(record.Document.ID, record.Revision.ID)) {
		return nil, nil, nil, false, shoal.NewError(
			shoal.ErrorInternal, "transactional document attempt is invalid",
		)
	}
	var head *RecordPublicationHead
	if attempt.ExpectedEpoch != 0 {
		head = &RecordPublicationHead{
			Epoch: attempt.ExpectedEpoch, LogicalDigest: attempt.ExpectedDigest,
		}
	}
	return &record, head, append([]byte(nil), attempt.Value...), true, nil
}

func intentPhysicalIdentity(cell Cell) string {
	var encoded []byte
	encoded = appendLength(encoded, []byte(cell.Table))
	for _, component := range [][]byte{
		cell.Row, cell.Family, cell.Qualifier, cell.Visibility,
	} {
		encoded = appendLength(encoded, component)
	}
	if cell.EpochTimestamp {
		encoded = append(encoded, 1)
	} else {
		encoded = append(encoded, 0)
	}
	return string(binary.BigEndian.AppendUint64(encoded, uint64(cell.Timestamp)))
}

func (s *IntentStore) attemptCoordinate(key []byte) (allocator.Coordinate, error) {
	if len(key) == 0 || len(key) > coordination.MaxOpaqueIDBytes {
		return allocator.Coordinate{}, errors.Join(
			transaction.ErrInvalid,
			errors.New("record attempt key is outside its bound"),
		)
	}
	row := append([]byte(nil), attemptRowMagic...)
	row = append(row, coordination.E(s.domain)...)
	row = append(row, coordination.E(key)...)
	return allocator.Coordinate{
		Row: row, Family: append([]byte(nil), intentFamily...),
		Qualifier:  append([]byte(nil), attemptQualifier...),
		Visibility: append([]byte(nil), s.visibility...),
	}, nil
}

func manifestIdentity(entry coordination.ManifestEntry) string {
	var encoded []byte
	for _, component := range [][]byte{
		entry.Table, entry.Row, entry.ColumnFamily, entry.ColumnQualifier,
	} {
		encoded = appendLength(encoded, component)
	}
	encoded = append(encoded, byte(entry.EpochSlot))
	encoded = binary.BigEndian.AppendUint64(encoded, uint64(entry.ExplicitTimestamp))
	encoded = append(encoded, entry.ValueDigest[:]...)
	return string(encoded)
}

