func (r *Runtime) recordIntentToken(
	ctx context.Context,
	request explorer.RecordPublication,
	recordKey []byte,
) ([]byte, error) {
	current, found, err := r.intents.Attempt(ctx, recordKey)
	if err != nil {
		return nil, err
	}
	if !found {
		return append([]byte(nil), request.Token...), nil
	}
	record, err := r.intents.Load(ctx, current)
	if err != nil {
		return nil, err
	}
	if r.intentMatchesRecord(record.Intent, request) {
		expected := record.Intent.Guards[0]
		if expected.ExpectedEpoch != request.ExpectedEpoch ||
			expected.ExpectedDigest != request.ExpectedDigest {
			return nil, transaction.ErrConflict
		}
		return append([]byte(nil), record.Intent.Token...), nil
	}
	snapshot, err := r.coordinator.Inspect(ctx, current)
	if err != nil {
		return nil, err
	}
	if !snapshot.Root.State.Terminal() ||
		snapshot.Root.State == coordination.StateCommitted {
		return nil, transaction.ErrConflict
	}
	if err := r.settleTerminalGuards(
		ctx,
		current,
		record.Intent,
		snapshot.Root.State,
	); err != nil {
		return nil, err
	}
	hash := sha256.New()
	writeDigestPart(hash, []byte("shoal-record-retry-v1"))
	writeDigestPart(hash, request.Token)
	writeDigestPart(hash, current)
	return hash.Sum(nil), nil
}

func (r *Runtime) recoverPending(
	ctx context.Context,
	txn coordination.TXN,
) error {
	for round := 0; round < r.recoveryRounds; round++ {
		err := r.recoverIntent(ctx, txn)
		if err == nil || !errors.Is(err, transaction.ErrUnavailable) {
			return err
		}
		record, loadErr := r.intents.Load(ctx, txn)
		if loadErr != nil {
			return errors.Join(err, loadErr)
		}
		advanced, available, waitErr := r.waitForExpectedResolution(
			ctx, txn, record.Intent,
		)
		if waitErr != nil {
			return errors.Join(err, waitErr)
		}
		if advanced || available {
			continue
		}
		timer := time.NewTimer(r.recoveryBackoff << min(round, 8))
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
	}
	return transaction.ErrUnavailable
}

func TestRecordBindingFailuresDoNotLeaveRecoverableOrphans(t *testing.T) {
	t.Run("invalid key", func(t *testing.T) {
		config := testRuntimeConfig(t, testDirectory(t))
		runtime, err := Open(config)
		if err != nil {
			t.Fatal(err)
		}
		defer runtime.Close()

		request := testRecordPublication("document", "revision", "value", nil)
		request.RecordKey = make([]byte, coordination.MaxOpaqueIDBytes+1)
		if _, err := runtime.PublishRecord(
			context.Background(),
			request,
		); !errors.Is(err, transaction.ErrInvalid) {
			t.Fatalf("oversized record key = %v", err)
		}
		if pending, err := runtime.PendingPublications(
			context.Background(),
		); err != nil || pending {
			t.Fatalf("pending publication after invalid key = %v, %v", pending, err)
		}
	})

	t.Run("definite conflict", func(t *testing.T) {
		config := testRuntimeConfig(t, testDirectory(t))
		runtime, err := Open(config)
		if err != nil {
			t.Fatal(err)
		}
		first := testRecordPublication("document-one", "revision-one", "one", nil)
		if _, err := runtime.PublishRecord(context.Background(), first); err != nil {
			t.Fatal(err)
		}
		second := testRecordPublication("document-two", "revision-two", "two", nil)
		second.RecordKey = append([]byte(nil), first.RecordKey...)
		if _, err := runtime.PublishRecord(
			context.Background(),
			second,
		); !errors.Is(err, transaction.ErrConflict) ||
			errors.Is(err, ErrIndeterminatePublication) {
			t.Fatalf("conflicting record binding = %v", err)
		}
		if pending, err := runtime.PendingPublications(
			context.Background(),
		); err != nil || pending {
			t.Fatalf("pending publication after binding conflict = %v, %v", pending, err)
		}
		if err := runtime.Close(); err != nil {
			t.Fatal(err)
		}

		reopened, err := Open(config)
		if err != nil {
			t.Fatal(err)
		}
		defer reopened.Close()
		head, err := reopened.RecordHead(
			context.Background(),
			second.EntityKind,
			second.EntityID,
		)
		if err != nil || head != nil {
			t.Fatalf("orphaned binding conflict was recovered = %#v, %v", head, err)
		}
	})
}

func mapPhysical(
	epoch coordination.Epoch,
	cells []transaction.PhysicalCell,
) ([]physicalCell, error) {
	if err := epoch.Validate(); err != nil {
		return nil, err
	}
	result := make([]physicalCell, len(cells))
	seen := make(map[string][]byte, len(cells))
	for index, cell := range cells {
		if err := cell.Entry.Validate(); err != nil {
			return nil, errors.Join(transaction.ErrInvalid, err)
		}
		if uint32(len(cell.Value)) != cell.Entry.ValueLength ||
			coordination.Sum(cell.Value) != cell.Entry.ValueDigest ||
			coordination.Sum(cell.Visibility) != cell.Entry.VisibilityDigest {
			return nil, fmt.Errorf("%w: physical cell %d disagrees with its manifest", transaction.ErrInternal, index)
		}
		table := string(cell.Entry.Table)
		if !validTableName(table) {
			return nil, fmt.Errorf("%w: physical table name is invalid", transaction.ErrInvalid)
		}
		timestamp := int64(cell.Entry.ExplicitTimestamp)
		if cell.Entry.EpochSlot == coordination.EpochSlotContent {
			timestamp = int64(epoch)
		}
		result[index] = physicalCell{
			table: table, row: append([]byte(nil), cell.Entry.Row...),
			family:     append([]byte(nil), cell.Entry.ColumnFamily...),
			qualifier:  append([]byte(nil), cell.Entry.ColumnQualifier...),
			visibility: append([]byte(nil), cell.Visibility...),
			value:      append([]byte(nil), cell.Value...), timestamp: timestamp,
		}
		key := physicalIdentity(result[index])
		if previous, ok := seen[key]; ok {
			if !bytes.Equal(previous, result[index].value) {
				return nil, fmt.Errorf("%w: duplicate physical key has divergent values", transaction.ErrInternal)
			}
			return nil, fmt.Errorf("%w: duplicate physical key", transaction.ErrInvalid)
		}
		seen[key] = result[index].value
	}
	return result, nil
}

