func (g *Governor) throttledErrorLocked(n int64) error {
	if required := float64(n); required > g.burst {
		waitSeconds := -g.tokens / g.rate
		if waitSeconds < 0 {
			waitSeconds = 0
		}
		return fmt.Errorf(
			"%w: %w: atomic %d-file reservation exceeds burst %.3f with rate debt outstanding; retry after at least %.3fs without another admission (rate balance %.3f at %.3f/s)",
			embeddingspace.ErrConvergenceUnavailable, ErrThrottled,
			n, g.burst, waitSeconds, g.tokens, g.rate)
	}
	return fmt.Errorf("%w: %w: %d permits requested, %.3f available at %.3f/s",
		embeddingspace.ErrConvergenceUnavailable, ErrThrottled, n, g.tokens, g.rate)
}

func markdownVisibleIndent(line string) (string, string) {
	index := 0
	columns := 0
	for index < len(line) {
		switch line[index] {
		case ' ':
			columns++
		case '\t':
			columns += 4 - columns%4
		default:
			if columns < 4 {
				return "", line
			}
			return strings.Repeat("\u00a0", columns), line[index:]
		}
		index++
	}
	return "", line
}

func markdownSetextUnderline(line string) bool {
	if line == "" || (line[0] != '=' && line[0] != '-') {
		return false
	}
	marker := line[0]
	index := 0
	for index < len(line) && line[index] == marker {
		index++
	}
	for ; index < len(line); index++ {
		if line[index] != ' ' && line[index] != '\t' {
			return false
		}
	}
	return true
}

func markdownHyphenThematicBreak(line string) bool {
	count := 0
	for _, r := range line {
		switch r {
		case '-':
			count++
		case ' ', '\t':
		default:
			return false
		}
	}
	return count >= 3
}

func markdownProse(value any) string {
	lines := strings.Split(sanitizeMarkdownText(fmt.Sprint(value)), "\n")
	var builder strings.Builder
	for i, line := range lines {
		if i > 0 {
			builder.WriteByte('\n')
		}
		indent, line := markdownVisibleIndent(line)
		builder.WriteString(indent)
		blockMarker := markdownBlockMarker(line)
		for index, r := range line {
			if index == blockMarker || strings.ContainsRune("\\`*_<&[]|", r) {
				builder.WriteByte('\\')
			}
			builder.WriteRune(r)
		}
	}
	return builder.String()
}

