// decodeRequest parses and validates one inbound envelope. Validation is
// strict: a message that does not declare JSON-RPC 2.0, or that carries no
// method, is rejected rather than processed on a guess.
func decodeRequest(raw []byte) (Request, *Error) {
	if !utf8.Valid(raw) || !json.Valid(raw) {
		return Request{}, newError(codeParseError, "invalid JSON")
	}
	trimmed := trimSpace(raw)
	if len(trimmed) == 0 || trimmed[0] != '{' {
		return Request{}, newError(codeInvalidRequest, "invalid request")
	}
	var request Request
	if err := json.Unmarshal(raw, &request); err != nil {
		return Request{}, newError(codeInvalidRequest, "invalid request")
	}
	if !validRequestID(request.ID) {
		return Request{}, newError(codeInvalidRequest, "invalid request ID")
	}
	if request.JSONRPC != jsonRPCVersion {
		return Request{}, newError(
			codeInvalidRequest, "unsupported jsonrpc version")
	}
	if request.Method == "" {
		return Request{}, newError(codeInvalidRequest, "method is required")
	}
	return request, nil
}

func ingestionAvailable(service webapi.Service) bool {
	availability, ok := service.(webapi.IngestAvailabilityProvider)
	return !ok || (!isAbsent(availability) && availability.IngestAvailable())
}

func newApplication(
	server stdioServer,
	closeFn func() error,
) (*application, error) {
	if isAbsent(server) {
		return nil, fmt.Errorf("MCP stdio server is required")
	}
	if closeFn == nil {
		return nil, fmt.Errorf("MCP workspace close function is required")
	}
	return &application{server: server, closeFn: closeFn}, nil
}

func strictDecodeOptional(raw json.RawMessage, value any) error {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || bytes.Equal(trimmed, []byte("null")) {
		return nil
	}
	return strictDecode(raw, value)
}

func publicToolFailure(err error) toolFailure {
	if errors.Is(err, context.Canceled) {
		return toolFailure{
			Code: string(shoal.ErrorCanceled), Message: "tool execution canceled"}
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return toolFailure{
			Code: string(shoal.ErrorDeadline), Message: "tool execution deadline exceeded"}
	}
	var public *shoal.Error
	if errors.As(err, &public) && public != nil {
		switch public.Code {
		case shoal.ErrorUnauthorized:
			return toolFailure{
				Code: string(public.Code), Message: "authorization denied"}
		case shoal.ErrorInternal:
			return toolFailure{
				Code: string(public.Code), Message: "tool execution failed"}
		default:
			message := strings.TrimSpace(public.Message)
			if message == "" {
				message = string(public.Code)
			}
			return toolFailure{Code: string(public.Code), Message: message}
		}
	}
	return toolFailure{
		Code: string(shoal.ErrorInternal), Message: "tool execution failed"}
}

