func protocolFailureID(raw []byte, failure *Error) (json.RawMessage, bool) {
	if failure == nil {
		return nil, false
	}
	if failure.Code == codeParseError {
		return json.RawMessage("null"), true
	}
	var envelope struct {
		ID json.RawMessage `json:"id"`
	}
	if err := json.Unmarshal(raw, &envelope); err != nil {
		return json.RawMessage("null"), true
	}
	if len(envelope.ID) == 0 {
		return json.RawMessage("null"), true
	}
	if string(envelope.ID) == "null" {
		return envelope.ID, true
	}
	if !validRequestID(envelope.ID) {
		return json.RawMessage("null"), true
	}
	return envelope.ID, true
}

// trimSpace removes leading and trailing ASCII whitespace without allocating.
func trimSpace(value []byte) []byte {
	start := 0
	for start < len(value) && isSpace(value[start]) {
		start++
	}
	end := len(value)
	for end > start && isSpace(value[end-1]) {
		end--
	}
	return value[start:end]
}

