// TestEntraAuthenticateCollapsesReasonsAtBoundary pins the exported trust
// boundary: Authenticate must return one and the same generic denial for every
// distinct internal failure reason. Distinct causes must be indistinguishable
// at the boundary, so a caller probing the endpoint cannot use the error as an
// oracle to tell "unknown kid" from "expired" from "wrong audience". This is a
// separate property from "no raw token leaks" (proved elsewhere): here the leak
// would be *which guard rejected*, which has reconnaissance value.
//
// The failure mode this guards against is a well-meaning future edit that, while
// debugging a login problem, returns the specific error from Authenticate
// instead of the generic denial. That change would keep every other test green;
// this one fails it, because the returned error becomes errors.Is-identifiable
// as a specific sentinel and the per-cause messages diverge.
func TestEntraAuthenticateCollapsesReasonsAtBoundary(t *testing.T) {
	issuer := newFakeIssuer(t)
	now := time.Now()
	authenticator := newTestAuthenticator(t, issuer.testConfig(fixedClock(now)))

	expired := issuer.defaultClaims(now)
	expired["exp"] = now.Add(-2 * time.Hour).Unix()
	wrongAudience := issuer.defaultClaims(now)
	wrongAudience["aud"] = "some-other-client-id"

	cases := []struct {
		name  string
		token string
	}{
		{"expired", issuer.signRS256(t, testKID, expired)},
		{"wrong audience", issuer.signRS256(t, testKID, wrongAudience)},
		{"unknown kid", issuer.signRS256(t, "unknown-kid", issuer.defaultClaims(now))},
	}

	// The specific sentinels the internal path surfaces for these causes. The
	// boundary error must not be errors.Is-identifiable as any of them.
	forbidden := []struct {
		name string
		err  error
	}{
		{"jwt.ErrTokenExpired", jwt.ErrTokenExpired},
		{"jwt.ErrTokenInvalidAudience", jwt.ErrTokenInvalidAudience},
		{"errNoMatchingKey", errNoMatchingKey},
	}

	genericMessage := entraDenied().Error()
	for _, testCase := range cases {
		_, err := authenticator.Authenticate(bearerRequest(testCase.token))
		if err == nil {
			t.Fatalf("%s: the boundary accepted an invalid token", testCase.name)
		}
		for _, sentinel := range forbidden {
			if errors.Is(err, sentinel.err) {
				t.Fatalf(
					"%s: the boundary leaked the specific reason %s; distinct "+
						"causes must be indistinguishable at the boundary",
					testCase.name, sentinel.name)
			}
		}
		// Every distinct cause must yield the identical generic denial, so the
		// error text cannot be used as an oracle either.
		if got := err.Error(); got != genericMessage {
			t.Fatalf(
				"%s: boundary error %q is not the generic denial %q; the reason "+
					"leaks", testCase.name, got, genericMessage)
		}
	}
}

// TestEntraRejectsAlgorithmConfusion proves an HS256 token whose HMAC secret is
// the issuer's RSA public key is rejected — the classic RS256/HS256 confusion
// bypass. Like the alg:none test, it asserts the specific reason so the guard
// is observable: WithValidMethods refuses HS256 before the keyfunc, surfacing
// as jwt.ErrTokenSignatureInvalid. Remove that allowlist and the forged token
// reaches the keyfunc, which rejects it via the default arm with a *different*
// error (errUnexpectedSigningMethod / ErrTokenUnverifiable) — failing this
// assertion. So deleting either algorithm guard changes an observable outcome.
func TestEntraRejectsAlgorithmConfusion(t *testing.T) {
	issuer := newFakeIssuer(t)
	now := time.Now()
	authenticator := newTestAuthenticator(t, issuer.testConfig(fixedClock(now)))

	issuer.mu.Lock()
	publicN := issuer.keys[testKID].PublicKey.N.Bytes()
	issuer.mu.Unlock()

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, issuer.defaultClaims(now))
	token.Header["kid"] = testKID
	forged, err := token.SignedString(publicN)
	if err != nil {
		t.Fatalf("sign HS256 token: %v", err)
	}
	_, err = authenticator.authenticate(bearerRequest(forged))
	if !errors.Is(err, jwt.ErrTokenSignatureInvalid) {
		t.Fatalf(
			"HS256 confusion token was not rejected by the method allowlist "+
				"(want ErrTokenSignatureInvalid): %v", err)
	}
}

// TestSelectAuthenticatorEntraMisconfiguredFailsClosed proves an incomplete
// Entra configuration refuses rather than falling back to anonymous serving.
func TestSelectAuthenticatorEntraMisconfiguredFailsClosed(t *testing.T) {
	config := entraConfig{tenantID: testTenant} // no audience
	authenticator, err := selectAuthenticator(false, config, "0.0.0.0:8080", time.Now)
	if err == nil {
		t.Fatal("an incomplete Entra configuration was accepted")
	}
	if authenticator != nil {
		t.Fatal("a refused configuration still returned an authenticator")
	}
}

// TestEntraUnknownKidDoesNotStorm proves an unknown key identifier is rejected
// and, crucially, that a flood of unknown-kid tokens does not induce more than
// one JWKS refresh within the refresh interval. A remote attacker must not be
// able to turn token submission into a fetch amplifier.
func TestEntraUnknownKidDoesNotStorm(t *testing.T) {
	issuer := newFakeIssuer(t)
	now := time.Now()
	authenticator := newTestAuthenticator(t, issuer.testConfig(fixedClock(now)))

	for i := 0; i < 50; i++ {
		claims := issuer.defaultClaims(now)
		token := issuer.signRS256(t, "unknown-kid", claims)
		_, err := authenticator.authenticate(bearerRequest(token))
		if !errors.Is(err, errNoMatchingKey) {
			t.Fatalf(
				"unknown key identifier not rejected by our key lookup "+
					"(want errNoMatchingKey): %v", err)
		}
	}
	if hits := issuer.discoveryCount(); hits > 1 {
		t.Fatalf(
			"unknown key identifiers triggered %d metadata fetches; a remote "+
				"caller induced a refresh storm", hits)
	}
