				n + `","e":"` + e + `"}]}`,
		},
		{
			"duplicate key identifier",
			`{"keys":[` +
				`{"kty":"RSA","kid":"duplicate","n":"` + n + `","e":"` + e + `"},` +
				`{"kty":"RSA","kid":"duplicate","n":"` + n + `","e":"` + e + `"}` +
				`]}`,
		},
	} {
