  nodes: [{id: "node-a", labels: ["A"]}, {id: "node-b", labels: ["B"]}],
  edges: [derivedEdge, assertedEdge],
});
const buttons = scenario.ids["graph-edges"].querySelectorAll("button");
assert.strictEqual(buttons.length, 2, "each edge renders as a selectable button");
const derivedButton = buttons.find((button) => button.className.split(/\s+/).includes("derived"));
const assertedButton = buttons.find((button) => !button.className.split(/\s+/).includes("derived"));
assert.ok(derivedButton, "the derived edge must carry the derived class");
assert.match(derivedButton.textContent, /^◆/, "the derived edge must be marked distinctly");
assert.match(derivedButton.getAttribute("aria-label"), /^Derived edge,/);
assert.doesNotMatch(assertedButton.textContent, /^◆/, "the asserted edge must not be marked derived");
`)
}

// TestHTTPRecomputeReDerivesLatentAssertion posts the literal wire bytes the
// browser sends to /api/v1/derivation/recompute and pins the deterministic
// re-derivation contract end to end: byte-identical inputs fold to one digest,
// a stale digest reports drift, and a changed input surfaces the new detail.
func TestHTTPRecomputeReDerivesLatentAssertion(t *testing.T) {
	corpus, err := explorer.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	defer corpus.Close()
	sourceID := seedWebapiLatentWorkspace(t, corpus, "0.91", 42)

	server := startRecomputeServer(t, corpus)
	defer server.Close()

	assertionID := latentAssertionWireID(t, server.URL, sourceID)

	// Baseline capture: an empty caller digest has nothing to compare, so it
	// reports unchanged and returns the derivation detail plus a fresh digest.
	first := postRecompute(t, server.URL, assertionID, "")
	if !first.Unchanged {
		t.Fatalf("baseline recompute unchanged = false, want true: %+v", first)
	}
	if first.Digest == "" {
		t.Fatalf("baseline recompute produced an empty digest")
	}
	if first.Detail.Origin != "derived" {
		t.Fatalf("recompute detail origin = %q, want derived", first.Detail.Origin)
	}
	if first.Detail.Score != 0.91 {
		t.Fatalf("recompute detail score = %v, want 0.91", first.Detail.Score)
	}
	for label, value := range map[string]string{
		"embedding_model":         first.Detail.EmbeddingModel,
		"embedding_model_version": first.Detail.EmbeddingModelVersion,
		"similarity_metric":       first.Detail.SimilarityMetric,
		"iterator_name":           first.Detail.IteratorName,
	} {
		if value == "" {
			t.Fatalf("recompute detail %s is empty, want the producer identity", label)
		}
	}
	if first.Detail.Threshold != 0.85 {
		t.Fatalf("recompute detail threshold = %v, want 0.85", first.Detail.Threshold)
	}
	if len(first.Detail.IteratorOptions) < 2 {
		t.Fatalf("recompute detail iterator_options = %v, want at least two entries",
			first.Detail.IteratorOptions)
	}
	for _, id := range []string{first.Detail.AssertionID, first.Detail.DerivationID} {
		decoded, err := base64.RawURLEncoding.DecodeString(id)
		if err != nil || len(decoded) == 0 || string(decoded) == id {
			t.Fatalf("recompute response id %q is not wire-encoded base64url", id)
		}
	}
	if first.Detail.AssertionID != assertionID {
		t.Fatalf("recompute assertion_id = %q, want the request form %q",
			first.Detail.AssertionID, assertionID)
	}
	for _, option := range first.Detail.IteratorOptions {
		if _, err := base64.RawURLEncoding.DecodeString(option.Key); err != nil {
			t.Fatalf("iterator option key %q is not base64url", option.Key)
		}
		if _, err := base64.RawURLEncoding.DecodeString(option.Value); err != nil {
			t.Fatalf("iterator option value %q is not base64url", option.Value)
		}
	}

	// Byte-identical re-run: a second recompute of unchanged inputs reproduces
	// the same digest and reports unchanged for the matching caller digest.
	second := postRecompute(t, server.URL, assertionID, first.Digest)
	if second.Digest != first.Digest {
		t.Fatalf("second recompute digest = %q, want the stable %q",
			second.Digest, first.Digest)
	}
	if !second.Unchanged {
		t.Fatalf("recompute of an unchanged derivation reported drift: %+v", second)
	}

	// A stale caller digest reports drift even though the corpus has not moved,
	// and the fresh digest never depends on the caller-supplied digest.
	stale := postRecompute(t, server.URL, assertionID, "deadbeefstale")
	if stale.Unchanged {
		t.Fatalf("recompute with a stale digest reported unchanged: %+v", stale)
	}
	if stale.Digest != first.Digest {
		t.Fatalf("recompute digest must not depend on the caller digest: %q vs %q",
			stale.Digest, first.Digest)
	}
}

// TestRecomputeUsesStartedEmbeddedWorkspaceReadPath pins that the recompute
// endpoint reaches derivations through the production authorization wrapper the
// deployed binary installs, not a bare pkg/explorer client. It runs the real
// server (run + -dev-auth), reads the assertion id the browser would select,
// and posts the literal recompute wire bytes the browser sends.
func TestRecomputeUsesStartedEmbeddedWorkspaceReadPath(t *testing.T) {
	data := t.TempDir()
	sourceID := seedStartedLatentWorkspace(t, data)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	output := &lockedBuffer{}
	done := make(chan error, 1)
	go func() {
		done <- run(ctx, []string{
			"-data", data,
			"-listen", "127.0.0.1:0",
			"-dev-auth",
		}, output)
	}()
	baseURL := waitForListeningURL(t, output)
	getMeta(t, baseURL)

	request, err := json.Marshal(webapi.NeighborhoodRequest{
		NodeIDs: []shoal.ID{sourceID},
		Depth:   1, Fanout: 8, MaxNodes: 8,
	})
	if err != nil {
		t.Fatal(err)
	}
	var neighborhood webapi.NeighborhoodResponse
	if err := json.Unmarshal(
		postJSON(t, baseURL+"/api/v1/neighborhood", string(request)), &neighborhood,
	); err != nil {
		t.Fatalf("decode neighborhood: %v", err)
	}
	if len(neighborhood.Neighborhood.Assertions) != 1 {
		t.Fatalf("started workspace assertions = %d, want 1",
			len(neighborhood.Neighborhood.Assertions))
	}
	assertionID := neighborhood.Neighborhood.Assertions[0].ID()
	assertionWire := base64.RawURLEncoding.EncodeToString([]byte(assertionID))

	// Baseline: an empty caller digest reports unchanged and returns the fresh
	// digest plus the derivation detail, read through the authorized path.
	first := recomputeThroughStartedServer(t, baseURL, assertionWire, "")
	if !first.Unchanged {
		t.Fatalf("baseline recompute unchanged = false, want true: %+v", first)
	}
	if first.Detail.Origin != "derived" {
		t.Fatalf("recompute detail origin = %q, want derived", first.Detail.Origin)
	}
	if first.Detail.IteratorName != explorer.LatentLinkDefaultIteratorName {
		t.Fatalf("recompute detail iterator = %q, want the projection iterator",
			first.Detail.IteratorName)
	}
	if first.Digest == "" {
		t.Fatalf("baseline recompute produced an empty digest")
	}

	// Re-running the same derivation is byte-identical, so recompute with the
	// captured digest reports unchanged through the same authorized path.
	second := recomputeThroughStartedServer(t, baseURL, assertionWire, first.Digest)
	if !second.Unchanged || second.Digest != first.Digest {
		t.Fatalf("stable recompute reported drift: %+v", second)
	}

	// A stale caller digest reports drift while the fresh digest stays stable.
	stale := recomputeThroughStartedServer(t, baseURL, assertionWire, "stale-digest")
	if stale.Unchanged {
		t.Fatalf("recompute with a stale digest reported unchanged: %+v", stale)
	}
	if stale.Digest != first.Digest {
		t.Fatalf("recompute digest depended on the caller digest: %q vs %q",
			stale.Digest, first.Digest)
	}

	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("server did not shut down")
	}
}

// TestRecomputeIsScopedToTheCallingIdentity pins the authorization scope of the
// recompute endpoint. The endpoint takes a caller-supplied assertion ID, so
// without this pin a refactor that sourced the assertion outside the authorized
// read path would turn recompute into a cross-identity read of derived
// assertions — producer model, version, threshold, tessellation cell, and
// score — with the whole suite still green.
//
// Load-bearing: the refusal is produced by the authorized bounded read path,
// whose provenance-seed guard returns auth.ObjectNotFound rather than an empty
// success. Removing the seed check and the neighborhood filter together lets
// identity B read identity A's full derivation detail and fails this test.
//
// The third assertion is the one that matters most: B's failure for a real but
// unauthorized assertion must be byte-identical to its failure for an assertion
// that does not exist. Any difference between the two is an existence oracle.
func TestRecomputeIsScopedToTheCallingIdentity(t *testing.T) {
	f := newRecomputeAuthzFixture(t)

	// 1. The owning identity can recompute its own derived assertion.
	owned, err := f.serviceA.Recompute(f.ctxA, webapi.RecomputeDerivationRequest{
		AssertionID: f.assertionID,
	})
	if err != nil {
		t.Fatalf("owner recompute failed: %v", err)
	}
	if owned.Detail.AssertionID != f.assertionID {
		t.Fatalf("owner recompute returned assertion %q, want %q",
			owned.Detail.AssertionID, f.assertionID)
	}

	// 2. A different identity replaying the same real assertion ID is refused.
	unauthorized, err := f.serviceB.Recompute(
		f.ctxB, webapi.RecomputeDerivationRequest{AssertionID: f.assertionID})
	if err == nil {
		t.Fatalf("unauthorized identity recomputed another identity's "+
			"assertion: %+v", unauthorized)
	}
	if !shoal.IsErrorCode(err, shoal.ErrorNotFound) {
		t.Fatalf("unauthorized recompute error = %v, want not_found", err)
	}

	// 3. That refusal must be indistinguishable from one for an assertion that
	// was never derived at all.
	_, missingErr := f.serviceB.Recompute(
		f.ctxB, webapi.RecomputeDerivationRequest{
			AssertionID: shoal.ID("assertion-that-was-never-derived"),
		})
	withheld := serializedRecomputeError(t, err)
	missing := serializedRecomputeError(t, missingErr)
	if string(withheld) != string(missing) {
		t.Fatalf("recompute is an existence oracle:\n withheld = %s\n missing  = %s",
			withheld, missing)
	}
}

func newRecomputeAuthzFixture(t *testing.T) *recomputeAuthzFixture {
	t.Helper()
	corpus, err := explorer.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = corpus.Close() })

	authority := auth.NewAuthority()
	store := authorized.NewMemoryPolicyStore()
	scorer, _ := any(corpus).(authorized.VectorScorer)

	newClient := func(source, policy []byte) *authorized.Client {
		selector, err := authorized.NewStaticPolicySelector(source, policy)
		if err != nil {
			t.Fatal(err)
		}
		client, err := authorized.NewClient(authorized.Config{
			Base:             corpus,
			VectorScorer:     scorer,
			Resolver:         authority.Resolver(),
			PolicySelector:   selector,
			PolicyStore:      store,
			GenerationReader: authnGenerationReader{},
			Clock:            time.Now,
		})
		if err != nil {
			t.Fatal(err)
		}
		return client
	}

	clientA := newClient(authnSourceGranted, authnPolicyGranted)
	clientB := newClient(authnSourceOther, authnPolicyOther)

	ctxA, err := authority.Binder().Bind(
		context.Background(), authnPrincipal(t, "granted"))
	if err != nil {
		t.Fatal(err)
	}
	ctxB, err := authority.Binder().Bind(
		context.Background(), authnPrincipal(t, "other-grant"))
	if err != nil {
		t.Fatal(err)
	}

	// Identity A owns both endpoints of the latent link, so the derived
	// assertion is visible to A and to nobody else.
	var sourceID, targetID shoal.ID
	for index, source := range []explorer.Source{
		{
			URI:       "file:///authz-recompute-source.txt",
			Title:     "authz recompute source",
			MediaType: explorer.MediaTypeText,
			Content:   "authz recompute source",
		},
		{
			URI:       "file:///authz-recompute-target.txt",
			Title:     "authz recompute target",
			MediaType: explorer.MediaTypeText,
			Content:   "authz recompute target",
		},
	} {
		result, err := clientA.Ingest(ctxA, source)
		if err != nil {
			t.Fatal(err)
		}
		if index == 0 {
			sourceID = result.Document.ID
		} else {
			targetID = result.Document.ID
		}
	}
	if err := corpus.PutLatentLinkCells(
		context.Background(), []explorer.LatentLinkCell{{
			Row:             []byte("cell-authz:" + string(sourceID)),
			ColumnFamily:    []byte("link"),
			ColumnQualifier: []byte(targetID),
			Timestamp:       42,
			Value:           []byte("0.91"),
		}},
	); err != nil {
		t.Fatal(err)
	}

	serviceA, err := webapi.NewEmbeddedService(clientA)
	if err != nil {
		t.Fatal(err)
	}
	serviceB, err := webapi.NewEmbeddedService(clientB)
	if err != nil {
		t.Fatal(err)
	}

	fixture := &recomputeAuthzFixture{
		serviceA: serviceA, serviceB: serviceB,
		ctxA: ctxA, ctxB: ctxB, sourceID: sourceID,
	}
	fixture.assertionID = fixture.derivedAssertionID(t)
	return fixture
}

// TestRecomputeDigestSeparatesMetadataBoundaries pins the length prefixes in
// canonicalDerivationMetadata: iterator option keys and values are dynamic, so
// without them a delimiter buried inside a value could impersonate the boundary
// between one option and the next. These two option maps share the same naive
// "key=value|" concatenation and must still fold to different digests.
func TestRecomputeDigestSeparatesMetadataBoundaries(t *testing.T) {
	left := sampleDerivationDetail()
	left.IteratorOptions = shoal.Metadata{"a": "b|c", "d": "e"}
	right := sampleDerivationDetail()
	right.IteratorOptions = shoal.Metadata{"a": "b", "c|d": "e"}
	if derivationDigest(left) == derivationDigest(right) {
		t.Fatalf("iterator option maps collided across an unprefixed boundary")
	}
}

// latentAssertionWireID reads the derived similarity assertion through the same
// neighborhood endpoint the browser uses and returns its wire-encoded id.
func latentAssertionWireID(t *testing.T, baseURL string, sourceID shoal.ID) string {
	t.Helper()
	body := fmt.Sprintf(`{"snapshot":%s,"node_ids":[%q],"depth":1}`,
		recomputeEmptySnapshot, base64.RawURLEncoding.EncodeToString([]byte(sourceID)))
	var wire struct {
		Neighborhood struct {
			Assertions []struct {
				ID     string `json:"id"`
				Origin string `json:"origin"`
			} `json:"assertions"`
		} `json:"neighborhood"`
	}
	if err := json.Unmarshal(
		postJSON(t, baseURL+"/api/v1/neighborhood", body), &wire,
	); err != nil {
		t.Fatalf("decode neighborhood response: %v", err)
	}
	if len(wire.Neighborhood.Assertions) != 1 ||
		wire.Neighborhood.Assertions[0].Origin != "derived" {
		t.Fatalf("neighborhood assertions = %+v, want one derived assertion",
			wire.Neighborhood.Assertions)
	}
	return wire.Neighborhood.Assertions[0].ID
}

// TestRecomputeDigestChangesWithInputs pins that every derivation input the
// inspector reports is folded into the digest, so a reviewer who deletes any
// writeField line is caught: the mutated detail must produce a different digest.
func TestRecomputeDigestChangesWithInputs(t *testing.T) {
	baseline := derivationDigest(sampleDerivationDetail())
	mutations := map[string]func(*DerivationDetail){
		"assertion_id":            func(d *DerivationDetail) { d.AssertionID = shoal.ID("assertion:other") },
		"derivation_id":           func(d *DerivationDetail) { d.DerivationID = shoal.ID("derivation:other") },
		"origin":                  func(d *DerivationDetail) { d.Origin = "asserted" },
		"score":                   func(d *DerivationDetail) { d.Score = 0.92 },
		"embedding_model":         func(d *DerivationDetail) { d.EmbeddingModel = "other-embed" },
		"embedding_model_version": func(d *DerivationDetail) { d.EmbeddingModelVersion = "v9" },
		"similarity_metric":       func(d *DerivationDetail) { d.SimilarityMetric = "dot" },
		"threshold":               func(d *DerivationDetail) { d.Threshold = 0.5 },
		"tessellation_cell":       func(d *DerivationDetail) { d.TessellationCell = "cell-b" },
		"iterator_name":           func(d *DerivationDetail) { d.IteratorName = "other-iterator" },
		"provider":                func(d *DerivationDetail) { d.Provider = "other-provider" },
		"model":                   func(d *DerivationDetail) { d.Model = "other-model" },
		"model_version":           func(d *DerivationDetail) { d.ModelVersion = "v9" },
		"iterator_option_value":   func(d *DerivationDetail) { d.IteratorOptions["edgeCF"] = "other" },
		"iterator_option_key":     func(d *DerivationDetail) { d.IteratorOptions["extraKey"] = "1" },
	}
	for name, mutate := range mutations {
		detail := sampleDerivationDetail()
		mutate(&detail)
		if got := derivationDigest(detail); got == baseline {
			t.Fatalf("mutating %s did not change the digest", name)
		}
	}
}

func derivationDetail(assertion ontology.Assertion) (DerivationDetail, error) {
	if assertion.Origin() != ontology.AssertionDerived {
		return DerivationDetail{}, shoal.NewError(
			shoal.ErrorNotFound, "assertion is not derived")
	}
	evidence := assertion.Evidence()
	if len(evidence) != 1 {
		return DerivationDetail{}, shoal.NewError(
			shoal.ErrorNotFound, "derived assertion evidence is missing")
	}
	derivation, ok := evidence[0].Derivation()
	if !ok {
		return DerivationDetail{}, shoal.NewError(
			shoal.ErrorNotFound, "derived assertion derivation is missing")
	}
	provenance := assertion.Provenance()
	return DerivationDetail{
		AssertionID:           assertion.ID(),
		DerivationID:          derivation.ID(),
		Origin:                string(assertion.Origin()),
		Score:                 float64(derivation.Score()),
		EmbeddingModel:        derivation.EmbeddingModel(),
		EmbeddingModelVersion: derivation.EmbeddingModelVersion(),
		SimilarityMetric:      derivation.SimilarityMetric(),
		Threshold:             float64(derivation.Threshold()),
		TessellationCell:      derivation.TessellationCell(),
		IteratorName:          derivation.IteratorName(),
		IteratorOptions:       derivation.IteratorOptions(),
		Provider:              provenance.Provider(),
		Model:                 provenance.Model(),
		ModelVersion:          provenance.ModelVersion(),
	}, nil
}

// TestHTTPRecomputeRejectsUnknownDerivation pins that recomputing an identifier
// that is not a live derived assertion fails closed with not-found rather than
// answering with an empty or fabricated derivation.
func TestHTTPRecomputeRejectsUnknownDerivation(t *testing.T) {
	corpus, err := explorer.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	defer corpus.Close()
	seedWebapiLatentWorkspace(t, corpus, "0.91", 42)

	server := startRecomputeServer(t, corpus)
	defer server.Close()

	body := fmt.Sprintf(`{"snapshot":%s,"assertion_id":%q}`,
		recomputeEmptySnapshot,
		base64.RawURLEncoding.EncodeToString([]byte("missing-derivation")))
	status, payload := postJSONStatus(
		t, server.URL+"/api/v1/derivation/recompute", body)
	if status != http.StatusNotFound {
		t.Fatalf("recompute of an unknown derivation returned %d: %s", status, payload)
	}
}

func startRecomputeServer(t *testing.T, corpus *explorer.Explorer) *httptest.Server {
	t.Helper()
	service, err := webapi.NewEmbeddedService(corpus)
	if err != nil {
		t.Fatal(err)
	}
	server := httptest.NewUnstartedServer(nil)
	handler, err := webapi.NewHandler(service, server.Listener.Addr().String())
	if err != nil {
		server.Close()
		t.Fatal(err)
	}
	server.Config.Handler = handler
	server.Start()
	return server
}

